/* Shared interpretation for the screen and downloadable PDF. */
(function(root){
'use strict';
const E=typeof DMAEngine!=='undefined'?DMAEngine:require('./engine.js');
const data=typeof DMA_DATA!=='undefined'?DMA_DATA:require('./questions.js');
const contact=typeof DMAContact!=='undefined'?DMAContact:require('./contact.js');
const INSIGHTS={
 strategy:{low:'Svaren tyder på att den digitala riktningen behöver bli tydligare. Investeringar får större chans att skapa nytta när de kopplas till ett konkret affärsmål, resurser och en ansvarig.',mid:'Ni har delar av en digital grund på plats. Nästa steg är att koppla ihop initiativen och regelbundet följa upp vilken nytta de skapar.',high:'Svaren visar en bred digital inriktning och beredskap för förändring. Fortsätt pröva antagandena mot kundnytta och faktiska resultat.',action:'Välj ett prioriterat affärsproblem. Sätt ett mätbart mål, utse en ansvarig och reservera tid för ett avgränsat försök.',advanced:'Gå igenom portföljen av digitala initiativ. Avsluta det som inte ger nytta och skala upp det som fungerar.'},
 technology:{low:'Användningen av de uppräknade teknikerna är begränsad. Det är ett underlag för att undersöka behov, inte ett skäl att köpa fler verktyg.',mid:'Ni använder flera digitala lösningar. Mer nytta kan finnas i att få befintliga verktyg och arbetssätt att fungera bättre tillsammans.',high:'Ni beskriver en bred användning av både grundläggande och avancerad teknik. Nästa värde finns i förvaltning, integration och uppföljning.',action:'Kartlägg ett arbetsflöde med onödiga manuella moment. Pröva först om era befintliga verktyg kan lösa problemet.',advanced:'Följ upp nyttjandegrad, integrationer och kostnader för era viktigaste verktyg. Förenkla där lösningar överlappar.'},
 people:{low:'Kompetensutveckling och delaktighet har utrymme att stärkas. En mindre förändring som personalen förstår och kan påverka är en bra början.',mid:'Ni arbetar med kompetens och engagemang på flera sätt. Nästa steg är att göra lärandet regelbundet och fånga upp hur förändringarna påverkar vardagen.',high:'Svaren beskriver många insatser för lärande och delaktighet. Fortsätt följa upp om stödet når olika roller och leder till bättre arbetsförhållanden.',action:'Samla ett litet team från olika roller. Identifiera ett kompetensbehov och ordna ett praktiskt lärpass med tid att öva.',advanced:'Följ upp hur medarbetare använder nya kunskaper i arbetet och vilka grupper som behöver annat stöd.'},
 data:{low:'Svaren pekar på utvecklingsbehov inom datahantering eller säkerhet. Börja med att förstå vilka uppgifter som är viktigast och hur de skyddas.',mid:'Flera delar av datahantering och säkerhet finns på plats. Tydligt ansvar och praktiska kontroller kan göra arbetet mer tillförlitligt.',high:'Ni beskriver en bred uppsättning arbetssätt för data och säkerhet. Självskattningen behöver ändå kompletteras med praktiska kontroller av att skydden fungerar.',action:'Utse en ansvarig för ett viktigt informationsflöde och kontrollera åtkomst, säkerhetskopiering och återställning.',advanced:'Öva en incident och testa återställning från säkerhetskopia. Dokumentera vad som behöver förbättras.'},
 automation:{low:'De uppräknade AI- och automatiseringsteknikerna används i liten omfattning. Välj användningsfall efter nytta och förutsättningar, inte efter teknikens nyhetsvärde.',mid:'Ni överväger, testar eller använder flera automatiseringslösningar. Tydliga kvalitetskrav och mänsklig uppföljning hjälper er att avgöra vad som är redo att skalas.',high:'Flera former av AI och automatisering är långt införda. Följ fortsatt kvalitet, drift och mänsklig kontroll när förutsättningarna förändras.',action:'Välj en återkommande uppgift med tydlig nytta. Testa med okänsliga data och jämför tid och kvalitet med dagens arbetssätt.',advanced:'Granska ett befintligt automatiserat flöde: mät fel, undantag och tidsvinst och kontrollera att ansvar och reservrutiner är tydliga.'},
 green:{low:'Kopplingen mellan digitalisering och miljöarbete kan göras tydligare. Börja med ett konkret resursflöde där effekten går att följa.',mid:'Ni använder digitalisering för hållbarhet på flera sätt. Koppla initiativen till mätbara effekter och beakta också teknikens egen resursförbrukning.',high:'Svaren visar ett brett arbete med hållbar digitalisering. Fortsätt granska faktiska effekter över livscykeln och eventuella målkonflikter.',action:'Välj energi, material, transporter eller utrustning. Mät nuläget och testa en förändring med ett tydligt miljömål.',advanced:'Följ upp miljöeffekten av ett digitalt initiativ över hela livscykeln, inklusive utrustning och datalagring.'}
};
function reportText(s){const t=INSIGHTS[s.id];return {summary:s.score<35?t.low:s.score<70?t.mid:t.high,action:s.score<70?t.action:t.advanced};}

function create(answers,options={}){
 const scores=E.scores(answers);if(scores.overall===null)throw new Error('Complete all question groups before creating a report.');
 const sorted=[...scores.sectors].sort((a,b)=>a.score-b.score),lowest=sorted[0],highest=sorted[5];
 const securityGap=!answers.q8.values.includes(4)||!answers.q8.values.includes(5);
 const priorities=securityGap?[scores.sectors.find(s=>s.id==='data'),...sorted.filter(s=>s.id!=='data').slice(0,2)]:sorted.slice(0,3);
 const summary=highest.score-lowest.score<5?'Profilen är jämn mellan områdena. Välj utvecklingsinsats utifrån ert viktigaste affärsbehov och kontrollera först eventuella luckor i säkerhet och kompetens.':`Er högsta självskattning finns inom ${highest.name.toLowerCase()}. ${lowest.name} har störst utvecklingsutrymme enligt spelets modell. Skillnaderna är ett samtalsunderlag för prioritering, inte ett mått på affärsnytta.`;
 const responses=data.questions.map(q=>({id:q.id,number:q.number,title:q.title,prompt:q.prompt,type:q.type,none:q.type==='multi'&&answers[q.id].values.length===0,items:q.items.map((item,i)=>{
  const value=answers[q.id].values[i];
  const answer=q.type==='multi'?(answers[q.id].values.includes(i)?'Markerat':'Inte markerat'):q.type==='investment'?`Redan investerat: ${[1,3].includes(value)?'Ja':'Nej'}. Planerar investering: ${[2,3].includes(value)?'Ja':'Nej'}.`:q.labels[value];
  return {number:i+1,text:item,answer};
 })}));
 return {version:1,contact,responses,demo:!!options.demo,date:options.date||new Date().toLocaleDateString('sv-SE'),scores,level:E.level(scores.overall),summary,securityGap,priorities:priorities.map(s=>({...s,...reportText(s)})),insights:scores.sectors.map(s=>({...s,...reportText(s),level:E.level(s.score)}))};
}
const API={create,text:reportText};root.DMAReport=API;if(typeof module!=='undefined')module.exports=API;
})(typeof window!=='undefined'?window:globalThis);
